mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM courses
    WHERE id = #{courseId}
      AND deleted = 0
)

mapper.insert:
INSERT INTO course_comments (
    parent_comment_id, content, deleted, create_at, updated_at, user_id, course_id
) VALUES (
    NULL, #{content}, 0, NOW(), NOW(), #{userId}, #{courseId}
)
